<template><div class="projects-page">
  <header class="page-header"><div><div class="page-eyebrow">WORKSPACE / PROJECTS</div><h2>{{t('projects.title')}}</h2><p class="page-subtitle">{{t('projects.subtitle')}}</p></div><el-button type="primary" @click="showCreate=true">+ {{t('projects.newProject')}}</el-button></header>
  <section class="summary"><div><span>{{t('projects.activeProject')}}</span><strong>{{store.currentProject?.name||'—'}}</strong></div><div><span>{{t('projects.runtime')}}</span><strong class="healthy"><i/>TEST ONLINE</strong></div><div><span>OPENAPI</span><strong>18 endpoints</strong></div><div><span>{{t('projects.lastExecution')}}</span><strong>21:03 · 2 FAIL</strong></div></section>
  <main class="project-list panel">
    <div class="list-head"><span>{{t('projects.project')}}</span><span>{{t('projects.environment')}}</span><span>{{t('projects.sources')}}</span><span>{{t('projects.latestRun')}}</span><span>{{t('projects.readiness')}}</span><span></span></div>
    <button v-for="project in store.projects" :key="project.id" class="project-row" :class="{selected:store.currentProject?.id===project.id}" @click="openProject(project)">
      <div class="identity"><span class="project-mark">S</span><div><b>{{project.name}}</b><small>{{project.description||t('projects.noDescription')}}</small></div></div>
      <div><b class="env">TEST</b><small class="mono">{{project.baseUrl||'—'}}</small></div>
      <div class="source"><span><i class="ok"/>OpenAPI</span><span><i class="ok"/>Browser</span></div>
      <div><b class="result">16 PASS <em>2 FAIL</em></b><small>R-20260904 · 02m 34s</small></div>
      <div class="ready"><strong>92%</strong><i><em/></i></div><span class="arrow">→</span>
    </button>
    <div v-if="!store.projects.length" class="empty"><span>＋</span><b>{{t('projects.emptyTitle')}}</b><p>{{t('projects.emptyDesc')}}</p><el-button type="primary" @click="showCreate=true">{{t('projects.createFirst')}}</el-button></div>
  </main>
  <section class="next-step"><div><span>01</span><p><b>{{t('projects.connectEnvironment')}}</b>{{t('projects.connectEnvironmentDesc')}}</p></div><div><span>02</span><p><b>{{t('projects.importContract')}}</b>{{t('projects.importContractDesc')}}</p></div><div><span>03</span><p><b>{{t('projects.describeGoal')}}</b>{{t('projects.describeGoalDesc')}}</p></div></section>

  <el-dialog v-model="showCreate" :title="t('projects.createTitle')" width="440px" append-to-body><el-form :model="form" label-position="top"><el-form-item :label="t('projects.projectName')"><el-input v-model="form.name" placeholder="ShopSphere"/></el-form-item><el-form-item :label="t('projects.description')"><el-input v-model="form.description" type="textarea" :rows="2"/></el-form-item><el-form-item :label="t('projects.baseUrl')"><el-input v-model="form.baseUrl" placeholder="http://localhost:3001"/></el-form-item></el-form><template #footer><el-button @click="showCreate=false">{{t('common.cancel')}}</el-button><el-button type="primary" @click="createProject">{{t('common.create')}}</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">
import { ref } from 'vue';import { useI18n } from 'vue-i18n';import { useRouter } from 'vue-router';import { useAppStore } from '@/stores/app';import { projectApi } from '@/api';import { ElMessage } from 'element-plus/es/components/message/index.mjs';import type { TestProject } from '@/types'
const {t}=useI18n(),router=useRouter(),store=useAppStore();const showCreate=ref(false),form=ref({name:'',description:'',baseUrl:''})
async function openProject(project:TestProject){await store.selectProject(project);router.push('/workspace')}
async function createProject(){if(!form.value.name.trim()){ElMessage.warning(t('projects.nameRequired'));return}const user=JSON.parse(localStorage.getItem('user')||'{}');if(store.isDemoMode){const now=new Date().toISOString();const project:TestProject={id:Date.now(),userId:user.id||1,name:form.value.name,description:form.value.description,baseUrl:form.value.baseUrl,active:true,createdAt:now,updatedAt:now};store.projects.unshift(project);await store.selectProject(project)}else{await projectApi.create({...form.value,userId:user.id||1});await store.loadProjects(user.id||1)}ElMessage.success(t('projects.created'));showCreate.value=false;form.value={name:'',description:'',baseUrl:''}}
</script>
<style scoped>
.projects-page{height:100%;padding:16px 20px 24px;overflow:auto}.summary{display:grid;grid-template-columns:1.4fr repeat(3,1fr);margin-bottom:12px;border:1px solid var(--border-subtle);background:var(--bg-surface)}.summary>div{display:grid;gap:4px;min-height:58px;padding:10px 14px;border-left:1px solid var(--border-subtle)}.summary>div:first-child{border:0}.summary span{color:var(--text-muted);font-size:9px;text-transform:uppercase;letter-spacing:.06em}.summary strong{font-size:12px;font-weight:500}.healthy{color:var(--success)}.healthy i{display:inline-block;width:6px;height:6px;margin-right:6px;border-radius:50%;background:var(--success)}.project-list{overflow:hidden}.list-head,.project-row{display:grid;grid-template-columns:minmax(260px,1.4fr) minmax(190px,1fr) 150px 180px 110px 28px;align-items:center;padding:0 14px}.list-head{height:34px;background:var(--bg-elevated);color:var(--text-muted);font:9px var(--font-mono);text-transform:uppercase}.project-row{width:100%;min-height:76px;border:0;border-top:1px solid var(--border-subtle);background:transparent;color:var(--text-secondary);text-align:left;cursor:pointer}.project-row:hover{background:var(--bg-hover)}.project-row.selected{box-shadow:inset 2px 0 var(--primary)}.identity{display:flex;align-items:center;gap:11px}.project-mark{display:grid;place-items:center;width:32px;height:32px;border:1px solid var(--border-active);border-radius:6px;background:var(--bg-elevated);color:var(--primary);font:600 13px var(--font-mono)}.identity div,.project-row>div:not(.identity){display:grid;gap:4px}.identity b{color:var(--text-primary);font-size:13px}.identity small,.project-row small{color:var(--text-muted);font-size:10px}.env{width:max-content;padding:2px 6px;border:1px solid color-mix(in srgb,var(--primary) 40%,transparent);border-radius:3px;color:var(--primary);font:9px var(--font-mono)}.source{grid-template-columns:auto auto!important;justify-content:start;gap:12px!important;font-size:10px}.source span{white-space:nowrap}.source i{display:inline-block;width:5px;height:5px;margin-right:5px;border-radius:50%}.ok{background:var(--success)}.result{font:10px var(--font-mono);color:var(--success)}.result em{margin-left:8px;color:var(--danger)}.ready{grid-template-columns:30px 1fr!important;align-items:center}.ready strong{font:10px var(--font-mono)}.ready>i{height:3px;background:var(--bg-base)}.ready em{display:block;width:92%;height:100%;background:var(--success)}.arrow{color:var(--text-muted);text-align:right}.empty{display:grid;justify-items:center;gap:7px;padding:48px}.empty>span{font-size:24px;color:var(--primary)}.empty p{color:var(--text-muted);font-size:11px}.next-step{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin-top:12px;background:var(--border-subtle)}.next-step>div{display:grid;grid-template-columns:26px 1fr;gap:8px;padding:14px;background:var(--bg-surface)}.next-step>div>span{color:var(--primary);font:9px var(--font-mono)}.next-step p{display:grid;gap:4px;color:var(--text-muted);font-size:10px;line-height:1.45}.next-step b{color:var(--text-secondary);font-size:11px;font-weight:500}@media(max-width:1050px){.list-head,.project-row{grid-template-columns:1.4fr 1fr 130px 90px 20px}.list-head>:nth-child(4),.project-row>:nth-child(4){display:none}}@media(max-width:760px){.summary{grid-template-columns:1fr 1fr}.list-head{display:none}.project-row{grid-template-columns:1fr 90px 20px}.project-row>:nth-child(2),.project-row>:nth-child(3){display:none}.next-step{grid-template-columns:1fr}}
</style>
